    private static ushort SF001_SETUP(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF001: // SETUP SEI ;SET INTERRUPT MASK  (VSNDRM4.ASM:226)
                if (b.Due) return 0xF001;
                b.Spend(2);
                c.CC |= 0x10;
                goto case 0xF002;
            case 0xF002: // LDS #ENDRAM ;INITIALIZE STACK POINTER  (VSNDRM4.ASM:227)
                if (b.Due) return 0xF002;
                b.Spend(3);
                c.SP = 0x007F; Logic16(ref c.CC, c.SP);
                goto case 0xF005;
            case 0xF005: // LDX #SOUND ;INDEX TO PIA  (VSNDRM4.ASM:228)
                if (b.Due) return 0xF005;
                b.Spend(3);
                c.X = 0x0400; Logic16(ref c.CC, c.X);
                goto case 0xF008;
            case 0xF008: // CLR 1,X ;ACCESS DDRA  (VSNDRM4.ASM:229)
                if (b.Due) return 0xF008;
                b.Spend(7);
                ea = (ushort)(c.X + 0x01);
                b.Write((ushort)ea, Unary(ref c.CC, 0xF, b.Read((ushort)ea)));
                goto case 0xF00A;
            case 0xF00A: // CLR 3,X ;ACCESS DDRB  (VSNDRM4.ASM:230)
                if (b.Due) return 0xF00A;
                b.Spend(7);
                ea = (ushort)(c.X + 0x03);
                b.Write((ushort)ea, Unary(ref c.CC, 0xF, b.Read((ushort)ea)));
                goto case 0xF00C;
            case 0xF00C: // LDAA #$FF ;PA0-PA7  (VSNDRM4.ASM:231)
                if (b.Due) return 0xF00C;
                b.Spend(2);
                c.A = 0xFF; Logic(ref c.CC, c.A);
                goto case 0xF00E;
            case 0xF00E: // STAA 0,X ;SET SIDE A AS OUTPUTS  (VSNDRM4.ASM:232)
                if (b.Due) return 0xF00E;
                b.Spend(6);
                b.Write((ushort)(c.X + 0x00), c.A); Logic(ref c.CC, c.A);
                goto case 0xF010;
            case 0xF010: // CLR 2,X ;SET B SIDE AS INPUTS  (VSNDRM4.ASM:233)
                if (b.Due) return 0xF010;
                b.Spend(7);
                ea = (ushort)(c.X + 0x02);
                b.Write((ushort)ea, Unary(ref c.CC, 0xF, b.Read((ushort)ea)));
                goto case 0xF012;
            case 0xF012: // LDAA #$37 ;CB2 LOW, IRQ ALLOWED  (VSNDRM4.ASM:234)
                if (b.Due) return 0xF012;
                b.Spend(2);
                c.A = 0x37; Logic(ref c.CC, c.A);
                goto case 0xF014;
            case 0xF014: // STAA 3,X ;PROGRAM B CONTROL REG  (VSNDRM4.ASM:235)
                if (b.Due) return 0xF014;
                b.Spend(6);
                b.Write((ushort)(c.X + 0x03), c.A); Logic(ref c.CC, c.A);
                goto case 0xF016;
            case 0xF016: // LDAA #$3C ;CA2 SET INIT HIGH, NO IRQS  (VSNDRM4.ASM:236)
                if (b.Due) return 0xF016;
                b.Spend(2);
                c.A = 0x3C; Logic(ref c.CC, c.A);
                goto case 0xF018;
            case 0xF018: // STAA 1,X ;PROGRAM A SIDE  (VSNDRM4.ASM:237)
                if (b.Due) return 0xF018;
                b.Spend(6);
                b.Write((ushort)(c.X + 0x01), c.A); Logic(ref c.CC, c.A);
                goto case 0xF01A;
            case 0xF01A: // STAA HI ;START RANDOM GENERATOR  (VSNDRM4.ASM:238)
                if (b.Due) return 0xF01A;
                b.Spend(4);
                b.Write(0x00, c.A); Logic(ref c.CC, c.A);
                goto case 0xF01C;
            case 0xF01C: // CLI ;CLEAR INTERRUPTS  (VSNDRM4.ASM:239)
                if (b.Due) return 0xF01C;
                b.Spend(2);
                c.CC &= 0xEF;
                goto case 0xF01D;
            case 0xF01D: // BRA * ;WAIT FOR INTERRUPT  (VSNDRM4.ASM:240)
                if (b.Due) return 0xF01D;
                b.Spend(4);
                goto case 0xF01D;
        }
        return pc;
    }

    private static ushort SF01F_PLAY(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF01F: // PLAY STX XPLAY ;SAVE CURRENT INDEX  (VSNDRM4.ASM:245)
                if (b.Due) return 0xF01F;
                b.Spend(5);
                b.Write16(0x07, c.X); Logic16(ref c.CC, c.X);
                goto case 0xF021;
            case 0xF021: // LDX #DECAYZ ;SET TO MAXIMUM AMPLITUDE  (VSNDRM4.ASM:246)
                if (b.Due) return 0xF021;
                b.Spend(3);
                c.X = 0xF0C4; Logic16(ref c.CC, c.X);
                goto case 0xF024;
            case 0xF024: // STX XDECAY ;AND SAVE  (VSNDRM4.ASM:247)
                if (b.Due) return 0xF024;
                b.Spend(5);
                b.Write16(0x02, c.X); Logic16(ref c.CC, c.X);
                goto case 0xF026;
            case 0xF026: // LDAA #$80 ;LOAD ZERO AMPLITUDE  (VSNDRM4.ASM:248)
                if (b.Due) return 0xF026;
                b.Spend(2);
                c.A = 0x80; Logic(ref c.CC, c.A);
                return 0xF028;
        }
        return pc;
    }

    private static ushort SF028_PLAY1(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF028: // PLAY1 LDAB FREQ4 ;CHECK WHITE NOISE COUNTER  (VSNDRM4.ASM:249)
                if (b.Due) return 0xF028;
                b.Spend(3);
                c.B = b.Read(0x10); Logic(ref c.CC, c.B);
                goto case 0xF02A;
            case 0xF02A: // BPL PLAY3 ;NOT IN WHITE MODE  (VSNDRM4.ASM:250)
                if (b.Due) return 0xF02A;
                b.Spend(4);
                if (Branch(c.CC, 0xA)) return 0xF035;
                goto case 0xF02C;
            case 0xF02C: // LDAB RANDOM ;GET RANDOM NUMBER  (VSNDRM4.ASM:251)
                if (b.Due) return 0xF02C;
                b.Spend(3);
                c.B = b.Read(0x01); Logic(ref c.CC, c.B);
                goto case 0xF02E;
            case 0xF02E: // LSRB ;REDUCE IT  (VSNDRM4.ASM:252)
                if (b.Due) return 0xF02E;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0x4, c.B);
                goto case 0xF02F;
            case 0xF02F: // LSRB  (VSNDRM4.ASM:253)
                if (b.Due) return 0xF02F;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0x4, c.B);
                goto case 0xF030;
            case 0xF030: // LSRB  (VSNDRM4.ASM:254)
                if (b.Due) return 0xF030;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0x4, c.B);
                goto case 0xF031;
            case 0xF031: // INCB ;NOW NON-ZERO  (VSNDRM4.ASM:255)
                if (b.Due) return 0xF031;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0xC, c.B);
                return 0xF032;
        }
        return pc;
    }

    private static ushort SF032_PLAY2(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF032: // PLAY2 DECB ;TIME OUT COUNT  (VSNDRM4.ASM:256)
                if (b.Due) return 0xF032;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0xA, c.B);
                goto case 0xF033;
            case 0xF033: // BNE PLAY2  (VSNDRM4.ASM:257)
                if (b.Due) return 0xF033;
                b.Spend(4);
                if (Branch(c.CC, 0x6)) goto case 0xF032;
                return 0xF035;
        }
        return pc;
    }

    private static ushort SF035_PLAY3(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF035: // PLAY3 DEC FREQ1S ;COUNT DOWN OSC. 1  (VSNDRM4.ASM:258)
                if (b.Due) return 0xF035;
                b.Spend(6);
                ea = 0x0015;
                b.Write((ushort)ea, Unary(ref c.CC, 0xA, b.Read((ushort)ea)));
                goto case 0xF038;
            case 0xF038: // BEQ PLAY7 ;DO AN UPDATE  (VSNDRM4.ASM:259)
                if (b.Due) return 0xF038;
                b.Spend(4);
                if (Branch(c.CC, 0x7)) return 0xF086;
                goto case 0xF03A;
            case 0xF03A: // DEC FREQ2S ;COUNT DOWN OSC. 2  (VSNDRM4.ASM:260)
                if (b.Due) return 0xF03A;
                b.Spend(6);
                ea = 0x0016;
                b.Write((ushort)ea, Unary(ref c.CC, 0xA, b.Read((ushort)ea)));
                goto case 0xF03D;
            case 0xF03D: // BEQ PLAY8 ;DO AN UPDATE  (VSNDRM4.ASM:261)
                if (b.Due) return 0xF03D;
                b.Spend(4);
                if (Branch(c.CC, 0x7)) return 0xF08B;
                goto case 0xF03F;
            case 0xF03F: // DEC FREQ3S ;COUNT DOWN OSC. 3  (VSNDRM4.ASM:262)
                if (b.Due) return 0xF03F;
                b.Spend(6);
                ea = 0x0017;
                b.Write((ushort)ea, Unary(ref c.CC, 0xA, b.Read((ushort)ea)));
                goto case 0xF042;
            case 0xF042: // BEQ PLAY9 ;DO AN UPDATE  (VSNDRM4.ASM:263)
                if (b.Due) return 0xF042;
                b.Spend(4);
                if (Branch(c.CC, 0x7)) return 0xF090;
                goto case 0xF044;
            case 0xF044: // DEC FREQ4S ;COUNT DOWN WHITE NOISE  (VSNDRM4.ASM:264)
                if (b.Due) return 0xF044;
                b.Spend(6);
                ea = 0x0018;
                b.Write((ushort)ea, Unary(ref c.CC, 0xA, b.Read((ushort)ea)));
                goto case 0xF047;
            case 0xF047: // BNE PLAY1 ;DO THEM AGAIN  (VSNDRM4.ASM:265)
                if (b.Due) return 0xF047;
                b.Spend(4);
                if (Branch(c.CC, 0x6)) return 0xF028;
                goto case 0xF049;
            case 0xF049: // LDAB FREQ4 ;CHECK WHITE NOISE CONSTANT  (VSNDRM4.ASM:266)
                if (b.Due) return 0xF049;
                b.Spend(3);
                c.B = b.Read(0x10); Logic(ref c.CC, c.B);
                goto case 0xF04B;
            case 0xF04B: // BEQ PLAY1 ;FORGET IT  (VSNDRM4.ASM:267)
                if (b.Due) return 0xF04B;
                b.Spend(4);
                if (Branch(c.CC, 0x7)) return 0xF028;
                goto case 0xF04D;
            case 0xF04D: // ANDB #$7F ;STRIP FLAG BIT  (VSNDRM4.ASM:268)
                if (b.Due) return 0xF04D;
                b.Spend(2);
                c.B &= 0x7F; Logic(ref c.CC, c.B);
                goto case 0xF04F;
            case 0xF04F: // STAB FREQ4S ;SAVE WHITE NOISE COUNT  (VSNDRM4.ASM:269)
                if (b.Due) return 0xF04F;
                b.Spend(4);
                b.Write(0x18, c.B); Logic(ref c.CC, c.B);
                goto case 0xF051;
            case 0xF051: // LDAB RANDOM ;GET CURRENT RANDOM  (VSNDRM4.ASM:270)
                if (b.Due) return 0xF051;
                b.Spend(3);
                c.B = b.Read(0x01); Logic(ref c.CC, c.B);
                goto case 0xF053;
            case 0xF053: // ASLB ;DOUBLE  (VSNDRM4.ASM:271)
                if (b.Due) return 0xF053;
                b.Spend(2);
                c.B = Unary(ref c.CC, 0x8, c.B);
                goto case 0xF054;
            case 0xF054: // ADDB RANDOM ;TRIPLE  (VSNDRM4.ASM:272)
                if (b.Due) return 0xF054;
                b.Spend(3);
                c.B = Add(ref c.CC, c.B, b.Read(0x01), false);
                goto case 0xF056;
            case 0xF056: // ADDB #$0B ;ADD IN 11  (VSNDRM4.ASM:273)
                if (b.Due) return 0xF056;
                b.Spend(2);
                c.B = Add(ref c.CC, c.B, 0x0B, false);
                goto case 0xF058;
            case 0xF058: // STAB RANDOM ;VOILA...NEW RANDOM NUMBER  (VSNDRM4.ASM:274)
                if (b.Due) return 0xF058;
                b.Spend(4);
                b.Write(0x01, c.B); Logic(ref c.CC, c.B);
                goto case 0xF05A;
            case 0xF05A: // DEC CYCL4S ;COUNT DOWN DECAY  (VSNDRM4.ASM:275)
                if (b.Due) return 0xF05A;
                b.Spend(6);
                ea = 0x0028;
                b.Write((ushort)ea, Unary(ref c.CC, 0xA, b.Read((ushort)ea)));
                goto case 0xF05D;
            case 0xF05D: // BNE PLAY6 ;DON'T DECAY  (VSNDRM4.ASM:276)
                if (b.Due) return 0xF05D;
                b.Spend(4);
                if (Branch(c.CC, 0x6)) return 0xF06D;
                goto case 0xF05F;
            case 0xF05F: // LDAB CYCLE4 ;RELOAD COUNT  (VSNDRM4.ASM:277)
                if (b.Due) return 0xF05F;
                b.Spend(3);
                c.B = b.Read(0x1C); Logic(ref c.CC, c.B);
                goto case 0xF061;
            case 0xF061: // STAB CYCL4S ;AND SAVE  (VSNDRM4.ASM:278)
                if (b.Due) return 0xF061;
                b.Spend(4);
                b.Write(0x28, c.B); Logic(ref c.CC, c.B);
                goto case 0xF063;
            case 0xF063: // LDX XDECAY ;GET DECAY JUMP POINTER  (VSNDRM4.ASM:279)
                if (b.Due) return 0xF063;
                b.Spend(4);
                c.X = b.Read16(0x02); Logic16(ref c.CC, c.X);
                goto case 0xF065;
            case 0xF065: // DEX ;MOVE TO LESS AMPLITUDE  (VSNDRM4.ASM:280)
                if (b.Due) return 0xF065;
                b.Spend(4);
                c.X--; Flag(ref c.CC, Z, c.X == 0);
                goto case 0xF066;
            case 0xF066: // CPX #RDECAY+1 ;DONE?  (VSNDRM4.ASM:281)
                if (b.Due) return 0xF066;
                b.Spend(3);
                Cpx(ref c.CC, c.X, 0xF0BD);
                goto case 0xF069;
            case 0xF069: // BEQ PLAY12 ;YUP...BYE BYE  (VSNDRM4.ASM:282)
                if (b.Due) return 0xF069;
                b.Spend(4);
                if (Branch(c.CC, 0x7)) return 0xF0B9;
                goto case 0xF06B;
            case 0xF06B: // STX XDECAY ;SAVE NEW POINTER  (VSNDRM4.ASM:283)
                if (b.Due) return 0xF06B;
                b.Spend(5);
                b.Write16(0x02, c.X); Logic16(ref c.CC, c.X);
                return 0xF06D;
        }
        return pc;
    }

    private static ushort SF06D_PLAY6(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF06D: // PLAY6 LDAB RANDOM ;GET RANDOM AMPLITUDE  (VSNDRM4.ASM:284)
                if (b.Due) return 0xF06D;
                b.Spend(3);
                c.B = b.Read(0x01); Logic(ref c.CC, c.B);
