    private static ushort SF093_PLAY10(SoundBoard b, ushort pc)
    {
        var c = b.Cpu;
        int ea;
        switch (pc)
        {
            case 0xF093: // PLAY10 TST 24,X ;CHECK CYCLES AT FREQUENCY  (VSNDRM4.ASM:304)
                if (b.Due) return 0xF093;
                b.Spend(7);
