                b.Spend(4);
                if (Branch(c.CC, 0x6)) return 0xF0A9;
                goto case 0xF09B;
            case 0xF09B: // LDAB 12,X ;LOAD CYCLES AT FREQUENCY  (VSNDRM4.ASM:308)
                if (b.Due) return 0xF09B;
                b.Spend(5);
                c.B = b.Read((ushort)(c.X + 0x0C)); Logic(ref c.CC, c.B);
                goto case 0xF09D;
            case 0xF09D: // STAB 24,X ;SAVE IN COUNTER  (VSNDRM4.ASM:309)
                if (b.Due) return 0xF09D;
                b.Spend(6);
                b.Write((ushort)(c.X + 0x18), c.B); Logic(ref c.CC, c.B);
                goto case 0xF09F;
            case 0xF09F: // LDAB 00,X ;GET CURRENT FRQUENCY  (VSNDRM4.ASM:310)
                if (b.Due) return 0xF09F;
                b.Spend(5);
                c.B = b.Read((ushort)(c.X + 0x00)); Logic(ref c.CC, c.B);
                goto case 0xF0A1;
            case 0xF0A1: // ADDB 16,X ;ADD DELTA  (VSNDRM4.ASM:311)
                if (b.Due) return 0xF0A1;
                b.Spend(5);
                c.B = Add(ref c.CC, c.B, b.Read((ushort)(c.X + 0x10)), false);
                goto case 0xF0A3;
            case 0xF0A3: // CMPB 20,X ;COMPARE TO END  (VSNDRM4.ASM:312)
