                goto case 0xF0A7;
            case 0xF0A7: // STAB 00,X ;SAVE NEW CURRENT FREQUENCY  (VSNDRM4.ASM:314)
                if (b.Due) return 0xF0A7;
                b.Spend(6);
                b.Write((ushort)(c.X + 0x00), c.B); Logic(ref c.CC, c.B);
                return 0xF0A9;
        }
        return pc;
    }

