                goto case 0xF7D5;
            case 0xF7D5: // SUBA #$13+2  (VSNDRM4.ASM:1209)
                if (b.Due) return 0xF7D5;
                b.Spend(2);
                c.A = Sub(ref c.CC, c.A, 0x15, false);
