                b.Spend(6);
                c.X = b.Read16((ushort)(c.X + 0x00)); Logic16(ref c.CC, c.X);
                goto case 0xF7E0;
            case 0xF7E0: // JSR ,X  (VSNDRM4.ASM:1214)
                if (b.Due) return 0xF7E0;
                b.Spend(8);
                ea = (ushort)(c.X + 0x00); b.Push16(0xF7E2);
                return (ushort)ea;
            case 0xF7E2: // BRA IRQ3  (VSNDRM4.ASM:1215)
                if (b.Due) return 0xF7E2;
                b.Spend(4);
                return 0xF7F8;
            case 0xF7E4: // .3S CMPA #$20+2 ;;Fixme was: 3$  (VSNDRM4.ASM:1217)
                if (b.Due) return 0xF7E4;
                b.Spend(2);
                Sub(ref c.CC, c.A, 0x22, false);
                goto case 0xF7E6;
            case 0xF7E6: // BHI .4S  (VSNDRM4.ASM:1218)
                if (b.Due) return 0xF7E6;
                b.Spend(4);
                if (Branch(c.CC, 0x2)) goto case 0xF7EF;
