            case 0xF7E8: // SUBA #$1E+2 ;NOISE REQUEST  (VSNDRM4.ASM:1219)
                if (b.Due) return 0xF7E8;
                b.Spend(2);
                c.A = Sub(ref c.CC, c.A, 0x20, false);
                goto case 0xF7EA;
            case 0xF7EA: // JSR JKNOIS  (VSNDRM4.ASM:1220)
                if (b.Due) return 0xF7EA;
                b.Spend(9);
                b.Push16(0xF7ED);
                return 0xFF4A;
            case 0xF7ED: // BRA IRQ3  (VSNDRM4.ASM:1221)
                if (b.Due) return 0xF7ED;
                b.Spend(4);
                return 0xF7F8;
            case 0xF7EF: // .4S CMPA #$24+2 ;;Fixme was: 4$  (VSNDRM4.ASM:1223)
                if (b.Due) return 0xF7EF;
                b.Spend(2);
                Sub(ref c.CC, c.A, 0x26, false);
                goto case 0xF7F1;
            case 0xF7F1: // BHI IRQ3  (VSNDRM4.ASM:1224)
                if (b.Due) return 0xF7F1;
                b.Spend(4);
                if (Branch(c.CC, 0x2)) return 0xF7F8;
                goto case 0xF7F3;
            case 0xF7F3: // SUBA #$21+2  (VSNDRM4.ASM:1225)
                if (b.Due) return 0xF7F3;
                b.Spend(2);
                c.A = Sub(ref c.CC, c.A, 0x23, false);
                goto case 0xF7F5;
            case 0xF7F5: // JSR WALSH  (VSNDRM4.ASM:1226)
                if (b.Due) return 0xF7F5;
                b.Spend(9);
