                c.A = Add(ref c.CC, c.A, b.Read(0x08), false);
                goto case 0xF7FE;
            case 0xF7FE: // STAA XPLAY+1  (VSNDRM4.ASM:1234)
                if (b.Due) return 0xF7FE;
                b.Spend(4);
                b.Write(0x08, c.A); Logic(ref c.CC, c.A);
                goto case 0xF800;
            case 0xF800: // BCC ADDX1  (VSNDRM4.ASM:1235)
                if (b.Due) return 0xF800;
                b.Spend(4);
                if (Branch(c.CC, 0x4)) return 0xF805;
                goto case 0xF802;
            case 0xF802: // INC XPLAY  (VSNDRM4.ASM:1236)
                if (b.Due) return 0xF802;
                b.Spend(6);
                ea = 0x0007;
                b.Write((ushort)ea, Unary(ref c.CC, 0xC, b.Read((ushort)ea)));
                return 0xF805;
        }
