                if (b.Due) return 0xF810;
                b.Spend(5);
                c.B = Add(ref c.CC, c.B, b.Read((ushort)(c.X + 0x00)), true);
                goto case 0xF812;
            case 0xF812: // DEX  (VSNDRM4.ASM:1247)
                if (b.Due) return 0xF812;
                b.Spend(4);
                c.X--; Flag(ref c.CC, Z, c.X == 0);
                goto case 0xF813;
            case 0xF813: // CPX #$F000  (VSNDRM4.ASM:1248)
                if (b.Due) return 0xF813;
                b.Spend(3);
                Cpx(ref c.CC, c.X, 0xF000);
                goto case 0xF816;
            case 0xF816: // BNE NMI1  (VSNDRM4.ASM:1249)
                if (b.Due) return 0xF816;
                b.Spend(4);
                if (Branch(c.CC, 0x6)) goto case 0xF810;
                goto case 0xF818;
            case 0xF818: // CMPB 0,X  (VSNDRM4.ASM:1250)
                if (b.Due) return 0xF818;
                b.Spend(5);
