                goto case 0xF81C;
            case 0xF81C: // WAI  (VSNDRM4.ASM:1252)
                if (b.Due) return 0xF81C;
                b.Spend(9);
                b.PushAll(0xF81D); c.Waiting = true;
                return 0xF81D;
        }
        return pc;
    }

    private static ushort SF81D_NMI2(SoundBoard b, ushort pc)
