                if (Branch(c.CC, 0xA)) goto case 0xFAA8;
                goto case 0xFAAB;
            case 0xFAAB: // LDAA PWAVPT+1 ;PT TO NEXT BYTE OF 16 BYTE WAVE  (VSNDRM4.ASM:1453)
                if (b.Due) return 0xFAAB;
                b.Spend(3);
                c.A = b.Read(0x28); Logic(ref c.CC, c.A);
