                b.Spend(2);
                c.A = Unary(ref c.CC, 0xC, c.A);
                goto case 0xFAAE;
            case 0xFAAE: // ANDA #15  (VSNDRM4.ASM:1455)
                if (b.Due) return 0xFAAE;
                b.Spend(2);
                c.A &= 0x0F; Logic(ref c.CC, c.A);
                goto case 0xFAB0;
            case 0xFAB0: // ORAA #WAVSRT ;! WAVSRT MUST BE DIVISIBLE BY 16 !  (VSNDRM4.ASM:1456)
                if (b.Due) return 0xFAB0;
                b.Spend(2);
                c.A |= 0x10; Logic(ref c.CC, c.A);
                goto case 0xFAB2;
            case 0xFAB2: // STAA PWAVPT+1  (VSNDRM4.ASM:1457)
                if (b.Due) return 0xFAB2;
                b.Spend(4);
                b.Write(0x28, c.A); Logic(ref c.CC, c.A);
                goto case 0xFAB4;
            case 0xFAB4: // LDX PWAVPT  (VSNDRM4.ASM:1459)
                if (b.Due) return 0xFAB4;
                b.Spend(4);
                c.X = b.Read16(0x27); Logic16(ref c.CC, c.X);
                goto case 0xFAB6;
            case 0xFAB6: // LDAB ,X  (VSNDRM4.ASM:1460)
                if (b.Due) return 0xFAB6;
                b.Spend(5);
                c.B = b.Read((ushort)(c.X + 0x00)); Logic(ref c.CC, c.B);
                goto case 0xFAB8;
            case 0xFAB8: // STAB SOUND  (VSNDRM4.ASM:1461)
                if (b.Due) return 0xFAB8;
                b.Spend(5);
                b.Write(0x0400, c.B); Logic(ref c.CC, c.B);
                goto case 0xFABB;
            case 0xFABB: // ANDA #15 ;0 IFF RESTARTING WAVE  (VSNDRM4.ASM:1463)
                if (b.Due) return 0xFABB;
                b.Spend(2);
                c.A &= 0x0F; Logic(ref c.CC, c.A);
                goto case 0xFABD;
            case 0xFABD: // RTS  (VSNDRM4.ASM:1464)
                if (b.Due) return 0xFABD;
                b.Spend(5);
                return b.Pull16();
        }
        return pc;
