            case 0xFAF2: // ADDA SMPPER+1 ;UPDATE SAMPLE RATE ONCE EACH WAVE PLAY  (VSNDRM4.ASM:1499)
                if (b.Due) return 0xFAF2;
                b.Spend(3);
