            case 0xFAF6: // STAA SMPPER+1  (VSNDRM4.ASM:1501)
                if (b.Due) return 0xFAF6;
                b.Spend(4);
                b.Write(0x0D, c.A); Logic(ref c.CC, c.A);
                goto case 0xFAF8;
            case 0xFAF8: // STAB SMPPER ;24  (VSNDRM4.ASM:1502)
                if (b.Due) return 0xFAF8;
                b.Spend(4);
                b.Write(0x0C, c.B); Logic(ref c.CC, c.B);
                goto case 0xFAFA;
            case 0xFAFA: // ADDB GLBPRO  (VSNDRM4.ASM:1504)
                if (b.Due) return 0xFAFA;
                b.Spend(3);
                c.B = Add(ref c.CC, c.B, b.Read(0x22), false);
                goto case 0xFAFC;
            case 0xFAFC: // LDAA #MINPER ;AVOID SYNC ERRORS BY LIMITING PITCH.  (VSNDRM4.ASM:1505)
                if (b.Due) return 0xFAFC;
